ogische factoren de mogelijkheden van mensen beïnvloeden en hoe toevallige uitgangsposities langdurige gevolgen kunnen krijgen.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/24833/zwaarden-paarden-en-ziektekiemen.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/24833/zwaarden-paarden-en-ziektekiemen.html","sha256":"8481ee290fb1a08544f2b3688589e946b131351d4df8c3588cd23d9854562aa4","checkedAt":"2026-11-01T20:41:54.194Z","fact":"Hardback ISBN 9789049801595 verschijningsdatum 01/04/2012 NUR 680 Geschiedenis algemeen uitgever Uitgeverij Dwarsligger® taal Nederlands","sourceAuthors":"Jared Diamond"},{"url":"https://metadata.isbn.nl/24833/zwaarden-paarden-en-ziektekiemen.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789041714398","key":{"id":978200133},"before":null,"after":{"id":978200133,"title":"Het glazen kasteel","isbn_10":null,"isbn_13":"9789041714398","work_id":978100036,"cover_id":null,"language":"nld","publisher":"Rainbow","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041714398","key":{"edition_id":"@edition:9789041714398"},"before":null,"after":{"edition_id":"@edition:9789041714398","work_id":978100036,"bound_author_id":978300021,"bound_title":"Het glazen kasteel","bound_language":"nld","bound_isbn13":"9789041714398","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000469829_Het_glazen_kasteel_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1183162/het-glazen-kasteel.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z